use std::env;
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process::{self, Command};
use std::time::{Instant, SystemTime, UNIX_EPOCH};

const HELP_TEXT: &str = "\
a conventional changelog for the rest of us

Usage: executable [OPTIONS]

Options:
  -r, --repository <URL>  Repository used for generating commit and issue links (without the .git,
                          e.g. https://github.com/thoughtram/clog)
  -f, --from <COMMIT>     e.g. 12a8546
  -T, --format <STR>      The output format, defaults to markdown [default: markdown] [possible
                          values: markdown, json]
  -M, --major             Increment major version by one (Sets minor and patch to 0)
  -g, --git-dir <PATH>    Local .git directory (defaults to \"$(pwd)/.git\")
  -w, --work-tree <PATH>  Local working tree of the git project (defaults to \"$(pwd)\")
  -m, --minor             Increment minor version by one (Sets patch to 0)
  -p, --patch             Increment patch version by one
  -s, --subtitle <STR>    
  -t, --to <COMMIT>       e.g. 8057684 [default: HEAD]
  -o, --outfile <PATH>    Where to write the changelog (Defaults to stdout when omitted)
  -c, --config <COMMIT>   The Clog Configuration TOML file to use [default: .clog.toml]
  -i, --infile <PATH>     A changelog to append to, but *NOT* write to (Useful in conjunction with
                          --outfile)
      --setversion <VER>  e.g. 1.0.1
  -F, --from-latest-tag   use latest tag as start (instead of --from)
  -l, --link-style <STR>  The style of repository link to generate [default: github] [possible
                          values: github, gitlab, stash, cgit]
  -C, --changelog <PATH>  A previous changelog to prepend new changes to (this is like using the
                          same file for both --infile and --outfile and should not be used in
                          conjunction with either)
  -h, --help              Print help
  -V, --version           Print version


If your .git directory is a child of your project directory (most common, such as /myproject/.git)
AND not in the current working directory (i.e you need to use --work-tree or --git-dir) you only
need to specify either the --work-tree (i.e. /myproject) OR --git-dir (i.e. /myproject/.git), you
don't need to use both.

If using the --config to specify a clog configuration TOML file NOT in the current working directory
(meaning you need to use --work-tree or --git-dir) AND the TOML file is inside your project
directory (i.e. /myproject/.clog.toml) you do not need to use --work-tree or --git-dir.
";

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum OutputFormat {
    Markdown,
    Json,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum LinkStyle {
    Github,
    Gitlab,
    Stash,
    Cgit,
}

#[derive(Debug, Default)]
struct Cli {
    repository: Option<String>,
    from: Option<String>,
    format: OutputFormat,
    major: bool,
    git_dir: Option<PathBuf>,
    work_tree: Option<PathBuf>,
    minor: bool,
    patch: bool,
    subtitle: Option<String>,
    to: String,
    outfile: Option<PathBuf>,
    config: PathBuf,
    infile: Option<PathBuf>,
    setversion: Option<String>,
    from_latest_tag: bool,
    link_style: LinkStyle,
    changelog: Option<PathBuf>,
}

#[derive(Debug)]
struct Config {
    sections: Vec<SectionConfig>,
}

#[derive(Debug)]
struct SectionConfig {
    title: String,
    kinds: Vec<String>,
}

#[derive(Debug)]
struct CommitEntry {
    component: Option<String>,
    subject: String,
    full_sha: String,
    short_sha: String,
    closes: Option<IssueRef>,
    breaks_issue: Option<IssueRef>,
    has_breaking: bool,
}

#[derive(Debug)]
struct SectionOutput {
    title: String,
    commits: Vec<CommitEntry>,
}

#[derive(Debug, Clone)]
struct IssueRef {
    issue: String,
    issue_link: String,
}

#[derive(Debug)]
struct ParsedSubject {
    kind: String,
    component: Option<String>,
    subject: String,
}

fn main() {
    match run() {
        Ok(()) => {}
        Err(code) => process::exit(code),
    }
}

fn run() -> Result<(), i32> {
    let args: Vec<String> = env::args().collect();
    let cli = match parse_args(&args) {
        Ok(ParsedArgs::Run(cli)) => cli,
        Ok(ParsedArgs::Help) => {
            print!("{HELP_TEXT}");
            return Ok(());
        }
        Ok(ParsedArgs::Version) => {
            println!("clog 0.10.0");
            return Ok(());
        }
        Err(err) => {
            eprint!("{err}");
            return Err(2);
        }
    };

    if cli.git_dir.is_some() && cli.work_tree.is_some() {
        fatal_io();
    }

    let config_text = fs::read_to_string(&cli.config).unwrap_or_else(|_| fatal_io());
    let config = parse_config(&config_text).unwrap_or_else(|_| fatal_toml());

    let version = if let Some(version) = cli.setversion.clone() {
        Some(version)
    } else if cli.major || cli.minor || cli.patch {
        fatal_semver();
    } else {
        None
    };

    let timer = Instant::now();
    let date = current_utc_date_string();
    let repo = GitRepo::from_cli(&cli);
    let commits = collect_commits(&repo, &cli);
    let sections = build_sections(&config, commits, &cli);
    let rendered = render_output(
        &cli,
        version.as_deref(),
        &date,
        &sections,
        load_existing_text(&cli),
    );
    write_output(&cli, rendered).unwrap_or_else(|_| fatal_io());

    let millis = timer.elapsed().as_millis();
    println!("changelog written. (took {millis} ms)");
    Ok(())
}

enum ParsedArgs {
    Run(Cli),
    Help,
    Version,
}

fn parse_args(args: &[String]) -> Result<ParsedArgs, String> {
    let mut cli = Cli {
        format: OutputFormat::Markdown,
        to: "HEAD".to_string(),
        config: PathBuf::from(".clog.toml"),
        link_style: LinkStyle::Github,
        ..Cli::default()
    };

    let mut seen_from = false;
    let mut seen_from_latest_tag = false;
    let mut seen_changelog = false;
    let mut seen_infile = false;
    let mut seen_outfile = false;

    let mut i = 1usize;
    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-h" | "--help" => return Ok(ParsedArgs::Help),
            "-V" | "--version" => return Ok(ParsedArgs::Version),
            "-r" | "--repository" => {
                cli.repository = Some(next_value(args, &mut i, "--repository <URL>")?);
            }
            "-f" | "--from" => {
                if seen_from_latest_tag {
                    return Err(conflict_message(
                        "--from-latest-tag",
                        "--from <COMMIT>",
                        "executable --from-latest-tag",
                    ));
                }
                seen_from = true;
                cli.from = Some(next_value(args, &mut i, "--from <COMMIT>")?);
            }
            "-T" | "--format" => {
                let value = next_value(args, &mut i, "--format <STR>")?;
                cli.format = match value.as_str() {
                    "markdown" => OutputFormat::Markdown,
                    "json" => OutputFormat::Json,
                    _ => return Err(invalid_value_message("--format <STR>", &value, &["markdown", "json"])),
                };
            }
            "-M" | "--major" => cli.major = true,
            "-g" | "--git-dir" => {
                cli.git_dir = Some(PathBuf::from(next_value(args, &mut i, "--git-dir <PATH>")?));
            }
            "-w" | "--work-tree" => {
                cli.work_tree = Some(PathBuf::from(next_value(args, &mut i, "--work-tree <PATH>")?));
            }
            "-m" | "--minor" => cli.minor = true,
            "-p" | "--patch" => cli.patch = true,
            "-s" | "--subtitle" => {
                cli.subtitle = Some(next_value(args, &mut i, "--subtitle <STR>")?);
            }
            "-t" | "--to" => {
                cli.to = next_value(args, &mut i, "--to <COMMIT>")?;
            }
            "-o" | "--outfile" => {
                if seen_changelog {
                    return Err(conflict_message(
                        "--changelog <PATH>",
                        "--outfile <PATH>",
                        "executable --changelog <PATH>",
                    ));
                }
                seen_outfile = true;
                cli.outfile = Some(PathBuf::from(next_value(args, &mut i, "--outfile <PATH>")?));
            }
            "-c" | "--config" => {
                cli.config = PathBuf::from(next_value(args, &mut i, "--config <COMMIT>")?);
            }
            "-i" | "--infile" => {
                if seen_changelog {
                    return Err(conflict_message(
                        "--changelog <PATH>",
                        "--infile <PATH>",
                        "executable --changelog <PATH>",
                    ));
                }
                seen_infile = true;
                cli.infile = Some(PathBuf::from(next_value(args, &mut i, "--infile <PATH>")?));
            }
            "--setversion" => {
                cli.setversion = Some(next_value(args, &mut i, "--setversion <VER>")?);
            }
            "-F" | "--from-latest-tag" => {
                if seen_from {
                    return Err(conflict_message(
                        "--from <COMMIT>",
                        "--from-latest-tag",
                        "executable --from <COMMIT>",
                    ));
                }
                seen_from_latest_tag = true;
                cli.from_latest_tag = true;
            }
            "-l" | "--link-style" => {
                let value = next_value(args, &mut i, "--link-style <STR>")?;
                cli.link_style = match value.as_str() {
                    "github" => LinkStyle::Github,
                    "gitlab" => LinkStyle::Gitlab,
                    "stash" => LinkStyle::Stash,
                    "cgit" => LinkStyle::Cgit,
                    _ => {
                        return Err(invalid_value_message(
                            "--link-style <STR>",
                            &value,
                            &["github", "gitlab", "stash", "cgit"],
                        ))
                    }
                };
            }
            "-C" | "--changelog" => {
                if seen_infile {
                    return Err(conflict_message(
                        "--changelog <PATH>",
                        "--infile <PATH>",
                        "executable --changelog <PATH>",
                    ));
                }
                if seen_outfile {
                    return Err(conflict_message(
                        "--changelog <PATH>",
                        "--outfile <PATH>",
                        "executable --changelog <PATH>",
                    ));
                }
                seen_changelog = true;
                cli.changelog = Some(PathBuf::from(next_value(args, &mut i, "--changelog <PATH>")?));
            }
            _ if arg.starts_with('-') => {
                return Err(format!(
                    "error: unexpected argument '{arg}' found\n\nUsage: executable [OPTIONS]\n\nFor more information, try '--help'.\n"
                ));
            }
            _ => {
                return Err(format!(
                    "error: unexpected argument '{arg}' found\n\nUsage: executable [OPTIONS]\n\nFor more information, try '--help'.\n"
                ));
            }
        }
        i += 1;
    }

    Ok(ParsedArgs::Run(cli))
}

fn next_value(args: &[String], index: &mut usize, display: &str) -> Result<String, String> {
    if *index + 1 >= args.len() {
        return Err(format!(
            "error: a value is required for '{display}' but none was supplied\n\nFor more information, try '--help'.\n"
        ));
    }
    *index += 1;
    Ok(args[*index].clone())
}

fn conflict_message(primary: &str, conflicting: &str, usage: &str) -> String {
    format!(
        "error: the argument '{primary}' cannot be used with '{conflicting}'\n\nUsage: {usage}\n\nFor more information, try '--help'.\n"
    )
}

fn invalid_value_message(arg: &str, value: &str, possible: &[&str]) -> String {
    format!(
        "error: invalid value '{value}' for '{arg}'\n  [possible values: {}]\n\nFor more information, try '--help'.\n",
        possible.join(", ")
    )
}

fn parse_config(input: &str) -> Result<Config, ()> {
    #[derive(Clone, Copy, Eq, PartialEq)]
    enum Table {
        None,
        Clog,
        Sections,
        Other,
    }

    let mut table = Table::None;
    let mut saw_clog = false;
    let mut sections = Vec::new();

    for raw_line in input.lines() {
        let line = strip_comment(raw_line);
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        if trimmed.starts_with('[') && trimmed.ends_with(']') {
            table = match &trimmed[1..trimmed.len() - 1] {
                "clog" => {
                    saw_clog = true;
                    Table::Clog
                }
                "sections" => Table::Sections,
                _ => Table::Other,
            };
            continue;
        }

        match table {
            Table::None => return Err(()),
            Table::Clog => {
                if !trimmed.contains('=') {
                    return Err(());
                }
            }
            Table::Sections => {
                let Some((key_raw, value_raw)) = split_once_unquoted(trimmed, '=') else {
                    return Err(());
                };
                let title = parse_key(key_raw.trim()).ok_or(())?;
                let kinds = parse_string_array(value_raw.trim()).ok_or(())?;
                sections.push(SectionConfig { title, kinds });
            }
            Table::Other => {
                if !trimmed.contains('=') {
                    return Err(());
                }
            }
        }
    }

    if !saw_clog {
        return Err(());
    }

    Ok(Config { sections })
}

fn strip_comment(line: &str) -> String {
    let mut out = String::new();
    let mut in_single = false;
    let mut in_double = false;
    let mut escaped = false;

    for ch in line.chars() {
        if escaped {
            out.push(ch);
            escaped = false;
            continue;
        }
        match ch {
            '\\' if in_double => {
                out.push(ch);
                escaped = true;
            }
            '\'' if !in_double => {
                in_single = !in_single;
                out.push(ch);
            }
            '"' if !in_single => {
                in_double = !in_double;
                out.push(ch);
            }
            '#' if !in_single && !in_double => break,
            _ => out.push(ch),
        }
    }

    out
}

fn split_once_unquoted(input: &str, needle: char) -> Option<(&str, &str)> {
    let mut in_single = false;
    let mut in_double = false;
    let mut escaped = false;

    for (idx, ch) in input.char_indices() {
        if escaped {
            escaped = false;
            continue;
        }
        match ch {
            '\\' if in_double => escaped = true,
            '\'' if !in_double => in_single = !in_single,
            '"' if !in_single => in_double = !in_double,
            _ if ch == needle && !in_single && !in_double => {
                return Some((&input[..idx], &input[idx + ch.len_utf8()..]));
            }
            _ => {}
        }
    }

    None
}

fn parse_key(input: &str) -> Option<String> {
    if let Some(value) = parse_quoted_string(input) {
        return Some(value);
    }
    if input.is_empty() {
        return None;
    }
    Some(input.to_string())
}

fn parse_string_array(input: &str) -> Option<Vec<String>> {
    let trimmed = input.trim();
    if !trimmed.starts_with('[') || !trimmed.ends_with(']') {
        return None;
    }
    let inner = &trimmed[1..trimmed.len() - 1];
    let mut values = Vec::new();
    let mut cursor = inner.trim();

    if cursor.is_empty() {
        return Some(values);
    }

    while !cursor.is_empty() {
        let (value, rest) = parse_one_string(cursor)?;
        values.push(value);
        let rest = rest.trim_start();
        if rest.is_empty() {
            break;
        }
        if !rest.starts_with(',') {
            return None;
        }
        cursor = rest[1..].trim_start();
        if cursor.is_empty() {
            break;
        }
    }

    Some(values)
}

fn parse_one_string(input: &str) -> Option<(String, &str)> {
    let mut chars = input.chars();
    match chars.next()? {
        '"' => {
            let mut out = String::new();
            let mut escaped = false;
            for (idx, ch) in input[1..].char_indices() {
                if escaped {
                    out.push(match ch {
                        'n' => '\n',
                        'r' => '\r',
                        't' => '\t',
                        '"' => '"',
                        '\\' => '\\',
                        other => other,
                    });
                    escaped = false;
                    continue;
                }
                match ch {
                    '\\' => escaped = true,
                    '"' => return Some((out, &input[idx + 2..])),
                    _ => out.push(ch),
                }
            }
            None
        }
        '\'' => {
            for (idx, ch) in input[1..].char_indices() {
                if ch == '\'' {
                    return Some((input[1..idx + 1].to_string(), &input[idx + 2..]));
                }
            }
            None
        }
        _ => None,
    }
}

fn parse_quoted_string(input: &str) -> Option<String> {
    let input = input.trim();
    let (value, rest) = parse_one_string(input)?;
    if rest.trim().is_empty() {
        Some(value)
    } else {
        None
    }
}

#[derive(Clone, Debug)]
struct GitRepo {
    git_dir: Option<PathBuf>,
    work_tree: Option<PathBuf>,
}

impl GitRepo {
    fn from_cli(cli: &Cli) -> Self {
        Self {
            git_dir: cli.git_dir.clone(),
            work_tree: cli.work_tree.clone(),
        }
    }

    fn command(&self) -> Command {
        let mut cmd = Command::new("git");
        if let Some(work_tree) = &self.work_tree {
            cmd.arg("-C").arg(work_tree);
        }
        if let Some(git_dir) = &self.git_dir {
            cmd.arg("--git-dir").arg(git_dir);
        }
        cmd
    }
}

fn collect_commits(repo: &GitRepo, cli: &Cli) -> Vec<RawCommit> {
    let from = if cli.from_latest_tag {
        latest_tag(repo, &cli.to)
    } else {
        cli.from.clone()
    };

    let Some(from_ref) = from else {
        return Vec::new();
    };

    let mut cmd = repo.command();
    cmd.arg("log")
        .arg(format!("{from_ref}..{}", cli.to))
        .arg("--format=%H%x1f%s%x1f%b%x1e");

    let Ok(output) = cmd.output() else {
        return Vec::new();
    };
    if !output.status.success() {
        return Vec::new();
    }

    let text = String::from_utf8_lossy(&output.stdout);
    let mut commits = Vec::new();
    for record in text.split('\u{1e}') {
        if record.trim().is_empty() {
            continue;
        }
        let mut parts = record.split('\u{1f}');
        let Some(sha) = parts.next() else {
            continue;
        };
        let Some(subject) = parts.next() else {
            continue;
        };
        let body = parts.next().unwrap_or_default();
        commits.push(RawCommit {
            full_sha: sha.trim().to_string(),
            subject: subject.to_string(),
            body: body.to_string(),
        });
    }
    commits
}

fn latest_tag(repo: &GitRepo, to_ref: &str) -> Option<String> {
    let mut cmd = repo.command();
    cmd.arg("describe")
        .arg("--tags")
        .arg("--abbrev=0")
        .arg(to_ref);

    let output = cmd.output().ok()?;
    if !output.status.success() {
        return None;
    }
    let tag = String::from_utf8_lossy(&output.stdout).trim().to_string();
    if tag.is_empty() {
        None
    } else {
        Some(tag)
    }
}

#[derive(Debug)]
struct RawCommit {
    full_sha: String,
    subject: String,
    body: String,
}

fn build_sections(config: &Config, commits: Vec<RawCommit>, cli: &Cli) -> Vec<SectionOutput> {
    let mut sections = config
        .sections
        .iter()
        .map(|section| SectionOutput {
            title: section.title.clone(),
            commits: Vec::new(),
        })
        .collect::<Vec<_>>();

    for commit in commits {
        let Some(parsed) = parse_subject(&commit.subject) else {
            continue;
        };
        let Some(section_idx) = config
            .sections
            .iter()
            .position(|section| section.kinds.iter().any(|kind| kind == &parsed.kind))
        else {
            continue;
        };

        let closes = first_issue_ref(&commit.body, cli, false);
        let has_breaking = parsed.kind.contains('!') || contains_breaking_marker(&commit.body);
        let breaks_issue = if has_breaking {
            first_issue_ref(&commit.body, cli, true)
        } else {
            None
        };
        sections[section_idx].commits.push(CommitEntry {
            component: parsed.component,
            subject: parsed.subject,
            full_sha: commit.full_sha.clone(),
            short_sha: short_sha(&commit.full_sha),
            closes,
            breaks_issue,
            has_breaking,
        });
    }

    sections
        .into_iter()
        .filter(|section| !section.commits.is_empty())
        .collect()
}

fn parse_subject(subject: &str) -> Option<ParsedSubject> {
    let colon = subject.find(':')?;
    let head = &subject[..colon];
    let tail = &subject[colon + 1..];
    let mut bang = false;
    let mut head = head;
    if let Some(stripped) = head.strip_suffix('!') {
        bang = true;
        head = stripped;
    }

    let (kind_base, component) = if let Some(open) = head.find('(') {
        if !head.ends_with(')') {
            return None;
        }
        let kind = &head[..open];
        let scope = &head[open + 1..head.len() - 1];
        let component = if scope.is_empty() {
            None
        } else {
            Some(scope.to_string())
        };
        (kind, component)
    } else {
        (head, None)
    };

    if kind_base.is_empty() {
        return None;
    }

    let mut kind = kind_base.to_string();
    if bang {
        kind.push('!');
    }

    Some(ParsedSubject {
        kind,
        component,
        subject: tail.to_string(),
    })
}

fn contains_breaking_marker(body: &str) -> bool {
    let lower = body.to_ascii_lowercase();
    lower.contains("breaking change") || lower.contains("breaks #") || lower.contains("break #")
}

fn first_issue_ref(body: &str, cli: &Cli, breaks: bool) -> Option<IssueRef> {
    let lower = body.to_ascii_lowercase();
    let patterns = if breaks {
        &["breaks #", "break #", "breaking change: #"][..]
    } else {
        &[
            "closes #",
            "close #",
            "closed #",
            "fixes #",
            "fix #",
            "fixed #",
            "resolves #",
            "resolve #",
            "resolved #",
        ][..]
    };

    let mut best = None::<(usize, String)>;
    for pattern in patterns {
        if let Some(idx) = lower.find(pattern) {
            let number_start = idx + pattern.len();
            let digits = lower[number_start..]
                .chars()
                .take_while(|ch| ch.is_ascii_digit())
                .collect::<String>();
            if digits.is_empty() {
                if breaks {
                    best = Some((idx, String::new()));
                }
                continue;
            }
            match &best {
                Some((best_idx, _)) if idx >= *best_idx => {}
                _ => best = Some((idx, digits)),
            }
        }
    }

    let (_, issue) = best?;
    let issue_link = build_issue_link(cli.repository.as_deref(), cli.link_style, &issue);
    Some(IssueRef { issue, issue_link })
}

fn short_sha(full_sha: &str) -> String {
    full_sha.chars().take(8).collect()
}

fn render_output(
    cli: &Cli,
    version: Option<&str>,
    date: &str,
    sections: &[SectionOutput],
    existing: Option<String>,
) -> String {
    let file_style = cli.outfile.is_some() || cli.changelog.is_some() || existing.is_some();
    let mut rendered = match cli.format {
        OutputFormat::Markdown => render_markdown(version, cli.subtitle.as_deref(), date, sections, cli, file_style),
        OutputFormat::Json => render_json(version, cli.subtitle.as_deref(), date, sections, cli, file_style),
    };

    if let Some(existing) = existing {
        rendered.push_str(&existing);
    }

    rendered
}

fn render_markdown(
    version: Option<&str>,
    subtitle: Option<&str>,
    date: &str,
    sections: &[SectionOutput],
    cli: &Cli,
    file_style: bool,
) -> String {
    let version = version.unwrap_or("");
    let subtitle = subtitle.unwrap_or("");
    let hashes = "##";
    let mut out = String::new();
    out.push_str(&format!("<a name=\"{version}\"></a>\n"));
    out.push_str(&format!("{hashes} {version} {subtitle} ({date})"));

    if sections.is_empty() {
        if file_style {
            out.push_str("\n\n\n\n\n");
        } else {
            out.push_str("\n\n");
        }
        return out;
    }

    out.push_str("\n\n\n");
    for (section_idx, section) in sections.iter().enumerate() {
        out.push_str(&format!("#### {}\n\n", section.title));
        for commit in &section.commits {
            out.push_str(&render_markdown_commit(commit, cli));
            out.push('\n');
        }
        if section_idx + 1 < sections.len() {
            out.push('\n');
        }
    }

    if file_style {
        out.push_str("\n\n\n");
    }

    out
}

fn render_markdown_commit(commit: &CommitEntry, cli: &Cli) -> String {
    let mut line = if let Some(component) = &commit.component {
        format!("* **{component}:** {}", commit.subject)
    } else {
        format!("*  {}", commit.subject)
    };

    let commit_link = build_commit_link(cli.repository.as_deref(), cli.link_style, &commit.full_sha, &commit.short_sha);
    line.push_str(&format!(" ([{}]({})", commit.short_sha, commit_link));

    if let Some(closes) = &commit.closes {
        line.push_str(&format!(", closes [#{}]({})", closes.issue, closes.issue_link));
    }
    if commit.has_breaking {
        if let Some(issue) = &commit.breaks_issue {
            let issue_number = if issue.issue.is_empty() { "#".to_string() } else { format!("#{}", issue.issue) };
            line.push_str(&format!(", breaks [{}]({})", issue_number, issue.issue_link));
        } else {
            let fallback = break_fallback_link(cli.repository.as_deref(), cli.link_style);
            line.push_str(&format!(", breaks [#]({fallback})"));
        }
    }

    line.push(')');
    line
}

fn render_json(
    version: Option<&str>,
    subtitle: Option<&str>,
    date: &str,
    sections: &[SectionOutput],
    cli: &Cli,
    file_style: bool,
) -> String {
    let version_part = match version {
        Some(version) => format!("Some(\"{}\")", escape_json(version)),
        None => "None".to_string(),
    };
    let subtitle_part = match subtitle {
        Some(subtitle) => subtitle.to_string(),
        None => "null".to_string(),
    };

    let mut out = String::new();
    out.push_str("{\"header\":{");
    out.push_str(&format!(
        "\"version\":{version_part},\"patch_version\":false,\"subtitle\":{subtitle_part},\"date\":\"{}\"",
        escape_json(date)
    ));
    out.push_str("},\"sections\":");

    if sections.is_empty() {
        out.push_str("null");
    } else {
        out.push('[');
        for (section_idx, section) in sections.iter().enumerate() {
            if section_idx > 0 {
                out.push(',');
            }
            out.push_str("{\"title\":\"");
            out.push_str(&escape_json(&section.title));
            out.push_str("\",\"commits\":[");
            for (commit_idx, commit) in section.commits.iter().enumerate() {
                if commit_idx > 0 {
                    out.push(',');
                }
                out.push_str("{\"component\":");
                match &commit.component {
                    Some(component) => {
                        out.push('"');
                        out.push_str(&escape_json(component));
                        out.push('"');
                    }
                    None => out.push_str("null"),
                }
                out.push_str(",\"subject\":\"");
                out.push_str(&escape_json(&commit.subject));
                out.push_str("\",\"commit_link\":\"");
                out.push_str(&escape_json(&build_commit_link(
                    cli.repository.as_deref(),
                    cli.link_style,
                    &commit.full_sha,
                    &commit.short_sha,
                )));
                out.push_str("\",\"closes\":");
                if let Some(closes) = &commit.closes {
                    out.push_str(&format!(
                        "[{{\"issue\":{},\"issue_link\":\"{}\"}}]",
                        closes.issue,
                        escape_json(&closes.issue_link)
                    ));
                } else {
                    out.push_str("null");
                }
                out.push_str(",\"breaks\":");
                if commit.has_breaking {
                    out.push_str("[]");
                } else {
                    out.push_str("null");
                }
                out.push('}');
            }
            out.push_str("]}");
        }
        out.push(']');
    }

    out.push('}');

    if file_style {
        out.push_str("\n\n\n");
    }

    out
}

fn build_commit_link(repository: Option<&str>, style: LinkStyle, full_sha: &str, short_sha: &str) -> String {
    match repository {
        Some(repository) => match style {
            LinkStyle::Github | LinkStyle::Gitlab => format!("{repository}/commit/{full_sha}"),
            LinkStyle::Stash => format!("{repository}/commits/{full_sha}"),
            LinkStyle::Cgit => format!("{repository}/commit/?id={full_sha}"),
        },
        None => short_sha.to_string(),
    }
}

fn build_issue_link(repository: Option<&str>, style: LinkStyle, issue: &str) -> String {
    match (repository, style) {
        (Some(repository), LinkStyle::Github | LinkStyle::Gitlab) => {
            format!("{repository}/issues/{issue}")
        }
        _ => issue.to_string(),
    }
}

fn break_fallback_link(repository: Option<&str>, style: LinkStyle) -> String {
    match (repository, style) {
        (Some(repository), LinkStyle::Github | LinkStyle::Gitlab) => format!("{repository}/issues/"),
        _ => String::new(),
    }
}

fn load_existing_text(cli: &Cli) -> Option<String> {
    let path = cli
        .changelog
        .as_ref()
        .or(cli.infile.as_ref())?;
    match fs::read_to_string(path) {
        Ok(text) if !text.is_empty() => Some(text),
        Ok(_) => None,
        Err(_) => None,
    }
}

fn write_output(cli: &Cli, rendered: String) -> io::Result<()> {
    if let Some(path) = cli.changelog.as_ref().or(cli.outfile.as_ref()) {
        fs::write(path, rendered)
    } else {
        let mut stdout = io::stdout().lock();
        stdout.write_all(rendered.as_bytes())
    }
}

fn escape_json(input: &str) -> String {
    let mut out = String::new();
    for ch in input.chars() {
        match ch {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            other => out.push(other),
        }
    }
    out
}

fn current_utc_date_string() -> String {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();
    let days = (now.as_secs() / 86_400) as i64;
    let (year, month, day) = civil_from_days(days);
    format!("{year:04}-{month:02}-{day:02}")
}

fn civil_from_days(days_since_unix_epoch: i64) -> (i32, u32, u32) {
    let z = days_since_unix_epoch + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = mp + if mp < 10 { 3 } else { -9 };
    let year = y + if m <= 2 { 1 } else { 0 };
    (year as i32, m as u32, d as u32)
}

fn fatal_io() -> ! {
    eprintln!("\u{1b}[1;31merror:\u{1b}[0m fatal I/O error with output file");
    process::exit(1);
}

fn fatal_toml() -> ! {
    eprintln!("\u{1b}[1;31merror:\u{1b}[0m Failed to parse TOML configuration file");
    process::exit(1);
}

fn fatal_semver() -> ! {
    eprintln!(
        "\u{1b}[1;31merror:\u{1b}[0m Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format."
    );
    process::exit(1);
}

